package com.maxwai.nclientv3.utility;

import java.net.URI;

/** Resolves API media paths without discarding a server-supplied CDN host. */
public final class ImageUrlResolver {
    private ImageUrlResolver() { }

    /** Repair full URLs generated by older versions when reading saved metadata. */
    public static String restoreStored(String path, String siteHost, boolean thumbnail) {
        String resolved = resolve(path, siteHost, thumbnail);
        URI uri = URI.create(resolved);
        String host = uri.getHost();
        String corrected;
        if (("i1." + siteHost).equalsIgnoreCase(host)) corrected = "i." + siteHost;
        else if (("t1." + siteHost).equalsIgnoreCase(host)) corrected = "t." + siteHost;
        else return resolved;
        String suffix = resolved.substring(resolved.indexOf("://") + 3 + uri.getRawAuthority().length());
        return "https://" + corrected + (uri.getPort() == -1 ? "" : ":" + uri.getPort()) + suffix;
    }

    public static String resolve(String path, String host, boolean thumbnail) {
        if (path == null || path.trim().isEmpty())
            throw new IllegalArgumentException("Missing image path");
        String value = path.trim();
        if (value.startsWith("//")) value = "https:" + value;
        URI uri = URI.create(value);
        if (uri.isAbsolute()) {
            if (!"https".equalsIgnoreCase(uri.getScheme()) || uri.getHost() == null
                || uri.getRawUserInfo() != null)
                throw new IllegalArgumentException("Unsupported image URL");
            return uri.toString();
        }
        String relative = value.startsWith("/") ? value.substring(1) : value;
        return "https://" + (thumbnail ? "t." : "i.") + host + "/" + relative;
    }
}
